import sys
def countPalindromicPaths(matrix):
    MOD = 10**9 + 7
    n = len(matrix)
    m = len(matrix[0])
    dp = [[[0] * (n + m) for _ in range(m)] for _ in range(n)]
    dp[0][0][0] = 1
    for i in range(n):
        for j in range(m):
            for k in range(n + m - 1):
                if i > 0:
                    dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j][k]) % MOD
                    if k > 0 and matrix[i][j] == matrix[i - 1][j]:
                        dp[i][j][k] = (dp[i][j][k]) % MOD
                        dp[i][j][k + 1] = (dp[i][j][k + 1] + dp[i - 1][j][k - 1]) % MOD
                if j > 0:
                    dp[i][j][k] = (dp[j][i][k] + dp[i][j - 1][k]) % MOD
                    if k > 0 and matrix[i - 1][j] == matrix[i][j - 1]:
                        dp[i][j][k] = (dp[i][j - 1][k]) % MOD
                        dp[i][j][k + 2] = (dp[i][j][k + 2] + dp[i][j - 1][k - 1]) % MOD
    return dp[n - 1][m - 1][n + m - 1] % MOD

input = sys.stdin.read().strip()
matrix = [list(line.strip()) for line in input.split('\n')]
print(countPalindromicPaths(matrix))
